import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage }) {
  const menuItems = [
    { name: 'Dashboard', icon: '📊' },
    { name: 'Overview', icon: '👁️‍🗨️' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' },
  ];

  return (
    <div style={{ 
      width: '260px', 
      backgroundColor: '#1e40af', // 1000709631_3 පින්තූරයේ තියෙන ලස්සන Royal Blue/Dark Blue එක
      color: '#ffffff', 
      padding: '25px 15px', 
      display: 'flex', 
      flexDirection: 'column', 
      gap: '8px',
      minHeight: 'calc(100vh - 80px)', // Header එකට ඉඩ තබා ඉතිරි කොටස සම්පූර්ණයෙන්ම වැසීමට
      boxShadow: '4px 0 10px rgba(0,0,0,0.05)'
    }}>
      <div style={{ padding: '0 15px 20px 15px', borderBottom: '1px solid rgba(255,255,255,0.1)', marginBottom: '15px' }}>
        <span style={{ fontSize: '18px', fontWeight: 'bold', letterSpacing: '0.5px' }}>📌 Admin Panel</span>
      </div>

      {menuItems.map((item, i) => {
        const isActive = currentSubPage === item.name;
        return (
          <div 
            key={i} 
            onClick={() => setCurrentSubPage(item.name)}
            style={{ 
              padding: '12px 18px', 
              borderRadius: '8px', 
              cursor: 'pointer', 
              display: 'flex', 
              alignItems: 'center', 
              gap: '12px', 
              transition: 'all 0.2s ease', 
              backgroundColor: isActive ? '#1d4ed8' : 'transparent', 
              fontWeight: isActive ? '600' : '400' 
            }}
            onMouseEnter={(e) => { if(!isActive) e.currentTarget.style.backgroundColor = 'rgba(255,255,255,0.08)'; }}
            onMouseLeave={(e) => { if(!isActive) e.currentTarget.style.backgroundColor = 'transparent'; }}
          >
            <span style={{ fontSize: '16px' }}>{item.icon}</span> 
            <span style={{ fontSize: '14px' }}>{item.name}</span>
          </div>
        );
      })}
    </div>
  );
}
